//! Replays the golden corpus generated by
//! `electricity/scripts/generate_agent_cli_corpus.py` -- real output from
//! `circuitry.agent_cli` -- against `electricity_tools::agent_cli` (issue
//! #520, part A).
//!
//! Parsed through [`electricity_json::loads`], not `serde_json::Value`:
//! several cases pin a schema's own authored key order (a `serde_json::
//! Value` round trip, a `BTreeMap`-backed `Map`, is alphabetical
//! regardless of the source text's own order -- the same reason
//! `prompt_schema_corpus.rs` avoids it).
//!
//! The corpus also carries `check_binary_cases`/`string_list_cases` for
//! part B's own later Rust port (`electricity-adapters`); this test only
//! replays the sections `electricity-tools::agent_cli` itself implements.

use electricity_tools::agent_cli::{
    AgentCliParseError, ClaudeCommandOpts, PI_ATTACHED_PROMPT_INSTRUCTION, PiCommandOpts,
    child_env, claude_command, claude_json_schema, parse_claude_output, parse_pi_output,
    pi_command,
};
use electricity_tools::process::Completed;
use electricity_value::Value;
use std::collections::HashMap;

static NONE: Value = Value::None;

fn field<'a>(dict: &'a Value, name: &str) -> &'a Value {
    dict.as_dict()
        .and_then(|d| d.get(&Value::Str(name.to_string())))
        .unwrap_or(&NONE)
}

fn str_field(dict: &Value, name: &str) -> Option<String> {
    field(dict, name).as_str().map(str::to_string)
}

fn bool_field(dict: &Value, name: &str) -> Option<bool> {
    field(dict, name).as_bool()
}

fn int_field(dict: &Value, name: &str) -> Option<i64> {
    as_i64(field(dict, name))
}

fn as_i64(value: &Value) -> Option<i64> {
    value
        .as_int()
        .and_then(|i| i.to_string().parse::<i64>().ok())
}

fn str_list_field(dict: &Value, name: &str) -> Option<Vec<String>> {
    field(dict, name).as_list().map(|items| {
        items
            .iter()
            .filter_map(|v| v.as_str().map(str::to_string))
            .collect()
    })
}

fn list_of_str(value: &Value) -> Vec<String> {
    value
        .as_list()
        .expect("expected a JSON array of strings")
        .iter()
        .map(|v| v.as_str().expect("expected a string").to_string())
        .collect()
}

fn corpus() -> Value {
    electricity_json::loads(include_str!("golden/agent_cli_corpus.json"))
        .expect("agent_cli_corpus.json must parse")
}

fn cases<'a>(corpus: &'a Value, key: &str) -> &'a [Value] {
    field(corpus, key).as_list().expect("expected a JSON array")
}

#[test]
fn replays_pi_command_cases() {
    let corpus = corpus();
    for case in cases(&corpus, "pi_command_cases") {
        let kwargs = field(case, "kwargs");
        let opts = PiCommandOpts {
            model: str_field(kwargs, "model").unwrap_or_default(),
            thinking: str_field(kwargs, "thinking").unwrap_or_default(),
            tools: bool_field(kwargs, "tools").unwrap_or(false),
            session_id: str_field(kwargs, "session_id"),
            persist_session: bool_field(kwargs, "persist_session").unwrap_or(false),
            extra_args: str_list_field(kwargs, "extra_args").unwrap_or_default(),
            instruction: str_field(kwargs, "instruction")
                .unwrap_or_else(|| PI_ATTACHED_PROMPT_INSTRUCTION.to_string()),
        };
        let argv = pi_command("pi", "/tmp/prompt.md", &opts);
        assert_eq!(argv, list_of_str(field(case, "expected")));
    }
}

#[test]
fn replays_claude_command_cases() {
    let corpus = corpus();
    for case in cases(&corpus, "claude_command_cases") {
        let kwargs = field(case, "kwargs");
        let json_schema = field(kwargs, "json_schema");
        let opts = ClaudeCommandOpts {
            model: str_field(kwargs, "model").unwrap_or_default(),
            json_schema: if json_schema.is_none() {
                None
            } else {
                Some(json_schema.clone())
            },
            tools: bool_field(kwargs, "tools").unwrap_or(false),
            session_id: str_field(kwargs, "session_id"),
            persist_session: bool_field(kwargs, "persist_session").unwrap_or(false),
            extra_args: str_list_field(kwargs, "extra_args").unwrap_or_default(),
            strict_mcp: bool_field(kwargs, "strict_mcp").unwrap_or(true),
        };
        let argv = claude_command("claude", &opts).expect("claude_command must not fail");
        assert_eq!(argv, list_of_str(field(case, "expected")));
    }
}

#[test]
fn replays_claude_json_schema_cases() {
    let corpus = corpus();
    for case in cases(&corpus, "claude_json_schema_cases") {
        let schema = field(case, "schema");
        let wrapped = claude_json_schema(schema);
        assert_eq!(&wrapped, field(case, "expected_schema"));
        let dumped = electricity_json::dumps(&wrapped, electricity_json::WriteMode::COMPACT)
            .expect("writable");
        assert_eq!(dumped, str_field(case, "expected_dumps").unwrap());
    }
}

#[test]
fn replays_child_env_cases() {
    let corpus = corpus();
    for case in cases(&corpus, "child_env_cases") {
        let base: HashMap<String, String> = field(case, "base")
            .as_dict()
            .expect("base must be an object")
            .iter()
            .map(|(k, v)| {
                (
                    k.as_str().unwrap().to_string(),
                    v.as_str().unwrap().to_string(),
                )
            })
            .collect();
        let unset_env = str_list_field(case, "unset_env").unwrap_or_default();
        let expected: HashMap<String, String> = field(case, "expected")
            .as_dict()
            .expect("expected must be an object")
            .iter()
            .map(|(k, v)| {
                (
                    k.as_str().unwrap().to_string(),
                    v.as_str().unwrap().to_string(),
                )
            })
            .collect();
        let got = child_env(&unset_env, &base);
        assert_eq!(got, expected);
    }
}

fn assert_matches_expected(
    result: Result<electricity_tools::agent_cli::AgentCliResult, AgentCliParseError>,
    expected: &Value,
) {
    let ok = field(expected, "ok");
    let error = field(expected, "error");
    let numeric_error = field(expected, "numeric_error");
    if !ok.is_none() {
        let got = result.expect("expected an ok result");
        assert_eq!(got.text, str_field(ok, "text").unwrap());
        assert_eq!(got.session_id, str_field(ok, "session_id"));
        assert_eq!(got.tokens_sent, int_field(ok, "tokens_sent"));
        assert_eq!(got.tokens_received, int_field(ok, "tokens_received"));
        assert_eq!(got.cost_usd, field(ok, "cost_usd").as_float());
        assert_eq!(got.finish_reason, str_field(ok, "finish_reason"));
        let expected_structured = field(ok, "structured_output");
        if expected_structured.is_none() {
            assert_eq!(got.structured_output, None);
        } else {
            assert_eq!(got.structured_output.as_ref(), Some(expected_structured));
        }
    } else if !error.is_none() {
        let err = result.expect_err("expected an error");
        assert_eq!(err.to_string(), error.as_str().unwrap());
    } else if !numeric_error.is_none() {
        let err = result.expect_err("expected a numeric error");
        match err {
            AgentCliParseError::Numeric(e) => {
                assert_eq!(
                    e.py_class.name(),
                    str_field(numeric_error, "py_class").unwrap()
                );
                assert_eq!(e.message, str_field(numeric_error, "message").unwrap());
            }
            other => panic!("expected a numeric error, got {other:?}"),
        }
    } else {
        panic!("corpus case has no recognized expected shape");
    }
}

#[test]
fn replays_parse_claude_output_cases() {
    let corpus = corpus();
    for case in cases(&corpus, "parse_claude_output_cases") {
        let proc = Completed {
            stdout: str_field(case, "stdout").unwrap_or_default(),
            stderr: str_field(case, "stderr").unwrap_or_default(),
            exit_code: as_i64(field(case, "returncode")).unwrap() as i32,
        };
        let schema_field = field(case, "json_schema");
        let schema = if schema_field.is_none() {
            None
        } else {
            Some(schema_field.clone())
        };
        let result = parse_claude_output(&proc, schema.as_ref());
        assert_matches_expected(result, field(case, "expected"));
    }
}

#[test]
fn replays_parse_pi_output_cases() {
    let corpus = corpus();
    for case in cases(&corpus, "parse_pi_output_cases") {
        let proc = Completed {
            stdout: str_field(case, "stdout").unwrap_or_default(),
            stderr: str_field(case, "stderr").unwrap_or_default(),
            exit_code: as_i64(field(case, "returncode")).unwrap() as i32,
        };
        let result = parse_pi_output(&proc);
        assert_matches_expected(result, field(case, "expected"));
    }
}
